#!/usr/bin/env python3
"""Veteran Upgrades: Patched Edition - game patcher (no installs needed: any Python 3).

  python3 patch_game.py status            # vanilla / patched / unknown
  python3 patch_game.py install           # back up empire.retail.dll, then patch it
  python3 patch_game.py restore           # put the original DLL back
  options: --game-dir "<Total War SHOGUN 2 folder>"   --force (see below)

What it does: changes a few hundred bytes of the game's empire.retail.dll so the mod can give abilities
to one unit type at a time. It only patches the exact Steam build it knows (checked by SHA-256), keeps
the original as empire.retail.dll.vanilla, and refuses anything it doesn't recognise (e.g. after a Steam
update) unless --force. Single-player only: restore before playing multiplayer. Steam's "Verify integrity
of game files" also undoes it.  (Generated by tools/make_patchers.py - do not edit.)
"""
import hashlib, os, re, shutil, sys

VANILLA_SHA256 = "022fae2e2da92b59b8b1b8ee52887003c624e3c8eca060b209f5d792a7f874f5"
PATCHED_SHA256 = "f594ecabcbf24b0757601a27b7f9f3c560fb0c37462a81139b5b2a6a3e4875b9"
SIGNATURE_OFFSET = 22675856
SIGNATURE = b"VU_ABILITY_PATCH "
PATCH_VERSION = "4"
EDITS = [  # (file offset, original bytes, patched bytes)
    (608, "3efc", "00fe"),
    (1382945, "1bcea700", "f7e64401"),
    (1383182, "2ecda700", "0ae64401"),
    (1383445, "a7caa700", "63e54401"),
    (1383495, "55caa700", "2de54401"),
    (1383545, "43caa700", "ffe44401"),
    (1694275, "0f84a9000000", "e9f825400190"),
    (1694450, "8b54242483c304", "e90d2640019090"),
    (12398941, "5fb80d0000005ec3", "e942d09c00909090"),
    (17970864, "568bf18b86", "31c0c20800"),
    (18166550, "83ec246a", "31c0c204"),
    (18371773, "b001", "30c0"),
    (18383873, "8a5c2408", "31db9090"),
    (22675520, "", ""),
]
GAME_FOLDER = "Total War SHOGUN 2"


def steam_roots():
    roots = [os.environ.get("STEAM_DIR")]
    if os.name == "nt":
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam") as k:
                roots.append(winreg.QueryValueEx(k, "SteamPath")[0])
        except OSError:
            pass
        roots += [r"C:\Program Files (x86)\Steam", r"C:\Program Files\Steam"]
    else:
        h = os.path.expanduser("~")
        roots += [f"{h}/.local/share/Steam", f"{h}/.steam/steam", f"{h}/.steam/root",
                  f"{h}/.var/app/com.valvesoftware.Steam/.local/share/Steam"]
    return [r for r in roots if r and os.path.isdir(r)]


def find_game():
    libs = []
    for root in steam_roots():
        libs.append(root)
        vdf = os.path.join(root, "steamapps", "libraryfolders.vdf")
        if os.path.exists(vdf):
            text = open(vdf, encoding="utf-8", errors="replace").read()
            libs += [p.replace("\\\\", "\\") for p in re.findall(r'"path"\s+"([^"]+)"', text)]
    for lib in libs:
        game = os.path.join(lib, "steamapps", "common", GAME_FOLDER)
        if os.path.exists(os.path.join(game, "empire.retail.dll")):
            return game
    return None


def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def has_signature(path):
    with open(path, "rb") as f:
        f.seek(SIGNATURE_OFFSET)
        return f.read(len(SIGNATURE)) == SIGNATURE


def state(dll):
    h = sha256(dll)
    if h == VANILLA_SHA256:
        return "vanilla"
    if h == PATCHED_SHA256:
        return "patched"
    if has_signature(dll):
        return "patched by another version of this patcher"
    return "unknown (not the Steam build this patcher knows - a Steam update?)"


def install(dll, force):
    s = state(dll)
    if s == "patched":
        print("Already patched."); return 0
    backup = dll + ".vanilla"
    if s == "vanilla":
        shutil.copy2(dll, backup)
    elif not (s.startswith("patched by") or force):
        print(f"Refusing: the game DLL is {s}. Verify the game files in Steam first, or use --force."); return 1
    if not (os.path.exists(backup) and sha256(backup) == VANILLA_SHA256):
        print("Refusing: no original backup. Verify the game files in Steam first."); return 1
    data = bytearray(open(backup, "rb").read())
    for off, old, new in EDITS:
        old, new = bytes.fromhex(old), bytes.fromhex(new)
        if data[off:off + len(old)] != old:
            print(f"Refusing: unexpected bytes at {off:#x}."); return 1
        data[off:off + len(new)] = new
    if hashlib.sha256(data).hexdigest() != PATCHED_SHA256:
        print("Refusing: the result doesn't match the expected patched file."); return 1
    tmp = dll + ".tmp"
    with open(tmp, "wb") as f:
        f.write(data)
    os.replace(tmp, dll)
    print(f"Patched (patch version {PATCH_VERSION}). Original saved as {os.path.basename(backup)}.")
    print("Single-player only: restore the game before playing multiplayer.")
    return 0


def restore(dll, force):
    s = state(dll)
    if s == "vanilla":
        print("The game is already original."); return 0
    if not (s.startswith("patched") or force):
        print(f"Refusing: the game DLL is {s}, not patched by this patcher. Verify the game files in Steam instead."); return 1
    backup = dll + ".vanilla"
    if not (os.path.exists(backup) and sha256(backup) == VANILLA_SHA256):
        print("No original backup found: use Steam's 'Verify integrity of game files' instead."); return 1
    shutil.copy2(backup, dll)
    print("Restored the original game DLL.")
    return 0


def main(argv):
    args = [a for a in argv if not a.startswith("--")]
    cmd = args[0] if args else "status"
    force = "--force" in argv
    game = None
    if "--game-dir" in argv:
        game = argv[argv.index("--game-dir") + 1]
    game = game or find_game()
    if not game or not os.path.exists(os.path.join(game, "empire.retail.dll")):
        print('Shogun 2 not found. Run again with --game-dir "<path to Total War SHOGUN 2>".'); return 1
    dll = os.path.join(game, "empire.retail.dll")
    print("Game:", game)
    if cmd == "status":
        print("Game DLL:", state(dll)); return 0
    if cmd == "install":
        return install(dll, force)
    if cmd == "restore":
        return restore(dll, force)
    print(__doc__); return 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
